import{_ as a}from"./chunks/architecture-layers.Z-RS_8yM.js";import{_ as d,o as e,c as r,a2 as i}from"./chunks/framework.BqDA2HS7.js";const _=JSON.parse('{"title":"架构：Python 核心与 DSH 插件","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),o={name:"architecture.md"};function l(n,t,h,c,p,s){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="架构-python-核心与-dsh-插件" tabindex="-1">架构：Python 核心与 DSH 插件 <a class="header-anchor" href="#架构-python-核心与-dsh-插件" aria-label="Permalink to &quot;架构：Python 核心与 DSH 插件&quot;">​</a></h1><p>RefractRouter 是单仓库、分层职责的结构：Python 核心拥有所有路由决策，TypeScript 插件只是宿主适配层。理解这条边界，是理解项目所有行为的第一步。</p><figure class="doc-diagram"><img src="'+a+'" alt="宿主层、插件层、Python 核心层与模型层的四层职责图"><figcaption>策略、准入、账本与证据只在 Python 核心出现一次；插件与网关都是这条权威实现的接入方式。</figcaption></figure><h2 id="为什么要这样分" tabindex="-1">为什么要这样分 <a class="header-anchor" href="#为什么要这样分" aria-label="Permalink to &quot;为什么要这样分&quot;">​</a></h2><p>模型路由的价值取决于决策的一致性和账目的可信度。如果选模规则同时存在于 Python 和 TypeScript，两边的行为偏差会直接导致实际调用与记录不符。因此项目约定：</p><ul><li>路由、评分、预算记账、Go/No-go 判定只实现一次，全部在 Python。</li><li>插件只做三件事：把宿主请求转成核心协议、把核心签发的调用交给宿主模型服务、 把结果和轨迹展示给用户。</li><li>核心不绑定 DSH：标准模型网关走 HTTP，Codex CLI 不需要 DSH 也能使用六策略。</li></ul><p>插件位于 validation/dsh/plugin/ 是历史原因；它现在是产品化入口之一，不是验证工具。 包名保留 dsh-refractrouter-validation 仅为兼容已安装版本。</p><h2 id="各层的具体职责" tabindex="-1">各层的具体职责 <a class="header-anchor" href="#各层的具体职责" aria-label="Permalink to &quot;各层的具体职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>位置</th><th>负责的事</th><th>明确不做的事</th></tr></thead><tbody><tr><td>宿主 Agent</td><td>DSH / Codex CLI</td><td>工具执行、权限审批、技能、上下文压缩、子 Agent</td><td>不决定用哪个模型</td></tr><tr><td>DSH 插件</td><td>validation/dsh/plugin/src/</td><td>宿主适配、设置卡片、DAG 图形、路由轨迹、进程生命周期</td><td>不计算路由、评分、预算</td></tr><tr><td>标准网关</td><td>src/refractrouter/model_gateway.py</td><td>HTTP Base URL、refract/* 虚拟模型、协议转换</td><td>不隐式进入 DAG</td></tr><tr><td>Python 核心</td><td>src/refractrouter/</td><td>六策略状态机、自动路由求解、Judge 合同、准入、账本、证据</td><td>不执行宿主工具、不管理会话</td></tr><tr><td>模型层</td><td>用户配置的 provider</td><td>实际推理与判别</td><td>—</td></tr></tbody></table><h2 id="一次规划路由调用的旅程" tabindex="-1">一次规划路由调用的旅程 <a class="header-anchor" href="#一次规划路由调用的旅程" aria-label="Permalink to &quot;一次规划路由调用的旅程&quot;">​</a></h2><p>以 DSH 中的一次 Stage 调用为例，数据这样流动：</p><ol><li>DSH 原生循环准备发起模型请求，插件拦截这个请求，通过本机子进程发给 Python 核心。</li><li>核心按冻结的任务状态和策略规则选出目标模型，原子预留预算后签发调用指令。</li><li>插件把调用转给 DSH 的模型服务，模型流式返回；工具调用原样交回 DSH 执行。</li><li>DSH 的工具结果作为结构化证据随下一轮请求回到核心，核心据此决定下一轮用哪个模型。</li><li>每次调用的费用、判别、接受或丢弃都写入本机证据文件，界面读取这些记录展示轨迹。</li></ol><p>这个循环里没有任何一步需要核心理解 DSH 的工具语义；核心只消费证据状态 （completed / failed / denied / unconfirmed），这正是它能同时服务 Codex 的原因。</p><h2 id="一次自动路由任务的旅程" tabindex="-1">一次自动路由任务的旅程 <a class="header-anchor" href="#一次自动路由任务的旅程" aria-label="Permalink to &quot;一次自动路由任务的旅程&quot;">​</a></h2><p>自动路由由核心独立调度（仍属研究入口）。任务整体进入核心后，先过零调用准入， 再判断是否值得为拆分付费；只有结构信号支持时才调用规划模型，然后比较 Direct 与 DAG 的完整成本。详见<a href="./automatic.html">自动路由</a>的流程图。</p><h2 id="核心模块速查" tabindex="-1">核心模块速查 <a class="header-anchor" href="#核心模块速查" aria-label="Permalink to &quot;核心模块速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>职责</th></tr></thead><tbody><tr><td>planning_runtime.py</td><td>规划路由主状态机：任务冻结、六策略流转、预算包络、证据持久化</td></tr><tr><td>planning_policy.py</td><td>Stage 信号计算、工具事件归一、Static 抽样</td></tr><tr><td>stage_hybrid.py</td><td>Stage 协作模式的判别合同与状态转换</td></tr><tr><td>planning_decision.py</td><td>Task 候选过滤、Judge 合同、结果严格校验</td></tr><tr><td>advisor_decision.py / escalation_decision.py</td><td>两个审核策略的独立判别合同</td></tr><tr><td>automatic_routing.py</td><td>自动路由两级求解：门控 + Direct/DAG 比较</td></tr><tr><td>model_gateway.py</td><td>标准模型 HTTP 服务，refract/* 虚拟模型</td></tr><tr><td>task_budget.py</td><td>原子预留、派发、结算，规划与 DAG 共用</td></tr></tbody></table><p>完整文件表见仓库的架构文档。</p><h2 id="语言边界的硬规则" tabindex="-1">语言边界的硬规则 <a class="header-anchor" href="#语言边界的硬规则" aria-label="Permalink to &quot;语言边界的硬规则&quot;">​</a></h2><ul><li>TypeScript 中不得出现路由、评分、预算或 Go/No-go 判定逻辑；插件可以在调用 Python 前检查部署级限制（比如宿主预算上限），但不能替核心做决策。</li><li>编译生成的 dist/ 是运行产物，不手写、不提交。</li><li>新增实现语言或跨层复制业务逻辑，须先在架构 Issue 或 ADR 中提案并获维护者批准。</li></ul><p>这些规则不是风格偏好，而是防止两个权威实现漂移的机制。历史事故与恢复核对记录在 仓库的 DAG 恢复核对文档中。</p>',21)])])}const f=d(o,[["render",l]]);export{_ as __pageData,f as default};
